export const agentLabel = (id: string) => AGENT_LABELS[id] ?? id[0].toUpperCase() + id.slice(1);

/** ``size: null`` leaves sizing to ``className`` (the older ui/AgentMark callers). */
export function AgentMark({ id, className = '', size = 14 }: { id: AgentId | string; className?: string; size?: number | null }) {
  const st = size == null ? undefined : { width: size, height: size, flex: 'none' as const };
  const uid = useId().replace(/[^a-zA-Z0-9_-]/g, '');
  if (id === 'claude' || id === 'cowork' || id === 'claude-cowork') {
    return (
      <svg viewBox="0 -.01 39.5 39.53" fill="none" className={className} style={st} aria-hidden="true">
        <path d={CLAUDE_PATH} fill="#d97757" />
      </svg>
    );
  }
  if (id === 'opencode') {
    // Official mark: anomalyco/opencode packages/ui/src/components/logo.tsx.
    return (
      <svg viewBox="0 0 16 20" fill="none" className={className} style={st} aria-hidden="true">
        <path d="M12 16H4V8H12V16Z" fill="currentColor" opacity="0.25" />
        <path d="M12 4H4V16H12V4ZM16 20H0V0H16V20Z" fill="currentColor" />
      </svg>
    );
  }
  if (id === 'hermes') {
    // Hermes Agent marks itself with the caduceus (☤) in its own CLI.
    return (
      <svg viewBox="0 0 16 16" className={className} style={st} aria-hidden="true">
        <text x="8" y="12.5" textAnchor="middle" fontSize="14" fill="currentColor">☤</text>
      </svg>
    );
  }
  const logo = LOGOS[LOGO_OF[id]];
  if (logo) {
    // Static, bundled SVG markup (not user input). Parts without their own
    // colour, and every part of a black brand mark, take the text colour.
    return (
      <svg viewBox={logo.viewBox} fill="currentColor" fillRule="evenodd" className={className} style={st} aria-hidden="true" dangerouslySetInnerHTML={{ __html: logo.body.split('__U__').join(uid) }} />
    );
  }
  if (id !== 'cursor' && id !== 'cursor-ide') {
    // No official mark to use: the agent's initial in a hairline square, so a
    // list of many agents still scans by letter instead of identical circles.
    const initial = (AGENT_LABELS[id] ?? id).replace(/[^A-Za-z0-9]/g, '')[0]?.toUpperCase() ?? '?';
    return (
      <svg viewBox="0 0 16 16" className={className} style={st} aria-hidden="true">
        <rect x="1.25" y="1.25" width="13.5" height="13.5" rx="3.5" fill="none" stroke="currentColor" strokeWidth="1.2" opacity="0.55" />
        <text x="8" y="11.4" textAnchor="middle" fontSize="9" fontWeight="600" fontFamily="var(--v-mono, ui-monospace)" fill="currentColor">{initial}</text>
      </svg>
    );
  }
  return (
    <svg viewBox="0 0 466.73 532.09" fill="none" className={className} style={st} aria-hidden="true">
      <path d={CURSOR_PATH} fill="currentColor" />
    </svg>
  );
}
